      // BrokerEntry[]\n            this._seq      = 0;\n        }\n\n        setPolicy(mountId, capability, value) {\n            if (!['auto', 'ask', 'never'].includes(value)) {\n                throw new Error('KernelBroker.setPolicy: invalid value ' + value);\n            }\n            this._policy.set(`${mountId}|${capability}`, value);\n        }\n\n        getPolicy(mountId, capability) {\n            return this._policy.get(`${mountId}|${capability}`) || defaultPolicyFor(capability);\n        }\n\n        // Called BEFORE relaying a request to a child. Returns { decision, entryId }.\n        // entryId is the opaque handle for finalize(); robust under concurrent ops on the\n        // same (mountId, op, path) tuple (review N3).\n        async mediate(op, mountId, path, credentialClass) {\n            credentialClass = credentialClass || 'none';\n            const cap    = capabilityFor(op);\n            const policy = this.getPolicy(mountId, cap);\n\n            let decision = 'deny';\n            if (policy === 'auto')       decision = 'allow';\n            else if (policy === 'never') decision = 'deny';\n            else if (policy === 'ask') {\n                if (this._ui && typeof this._ui.prompt === 'function') {\n                    try { decision = await this._ui.prompt({ op, mountId, path, credentialClass }); }\n                    catch (_) { decision = 'deny'; }\n                    if (decision !== 'allow' && decision !== 'deny') decision = 'deny';\n                } else {\n                    decision = 'deny';                                 // fail-closed when no UI\n                }\n            }\n\n            const entryId = 'be-' + (++this._seq) + '-' + nowMs().toString(36);\n            this._log.push({\n                entryId,\n                ts:              nowMs(),\n                edge:            `${this._kernelId}\u25b6${mountId}`,\n                kernelId:        this._kernelId,\n                mountId,\n                op,\n                path,\n                credentialClass,\n                policy,\n                decision,\n                result:          'pending'\n            });\n            return { decision, entryId };\n        }\n\n        // Close an entry by its opaque id.\n        finalize(entryId, result) {\n            for (let i = this._log.length - 1; i >= 0; i--) {\n                if (this._log[i].entryId === entryId) {\n                    this._log[i].result = result;\n                    return true;\n                }\n            }\n            return false;                                              // silent (no throw)\n        }\n\n        log(opts) {\n            opts = opts || {};\n            if (opts.mountId) return this._log.filter(e => e.mountId === opts.mountId);\n            return this._log.slice();\n        }\n\n        clearLog() { this._log = []; this._seq = 0; }\n    }\n\n    globalThis.KernelBroker = KernelBroker;\n})();\n\n</script>\n<script>\n/* =================================================================================\n   KernelParent \u2014 parent-side ViV orchestration  (Phase 2, testable seam)\n\n   globalThis.KernelParent \u2014 owns this kernel's mount table + broker sidecar and\n   runs the cross-mount relay (Edge 2). This is the parent-side mirror of\n   kernel-app-handlers.js: it extracts the orchestration out of the DOM-coupled\n   app-shell.js so the relay + broker-mediation + mount lifecycle are unit-tested\n   against a real child kernel (no DOM, no mocks). The only piece that CANNOT move\n   here is the iframe spawn \u2014 that's injected as `spawnChannel`, so app-shell\n   supplies the `document.createElement('iframe')` + srcdoc path while tests supply\n   a MessageChannel-backed child running bootKernelOnPort.\n\n   Closes the same gap H1/M4 had on the child side: the orchestration that ships is\n   now the orchestration under test.\n\n   opts = {\n     kernelId            string \u2014 labels broker entries\n     spawnChannel(ref, creds) \u2192 Promise<SecureChannel>\n                         brings up a ready child channel (iframe + handshake +\n                         secrets + ready-wait on the app-shell side; a wired\n                         SecureChannel pair on the test side). MUST clean up its\n                         own resources (iframe) if it throws.\n     resolveCredentials(ref) \u2192 Promise<{ vaultKey, accessToken? }>\n     brokerUi            optional { prompt(req) \u2192 Promise<'allow'|'deny'> } for 'ask'\n   }\n   ================================================================================= */\n\n;(function () {\n    'use strict';\n\n    if (!globalThis.KernelMounts || !globalThis.KernelBroker) {\n        throw new Error('KernelParent requires KernelMounts + KernelBroker (load them first)');\n    }\n    const KMounts = globalThis.KernelMounts;\n    const KBroker = globalThis.KernelBroker;\n\n    function codeError(code, msg) { const e = new Error(msg); e.code = code; return e; }\n\n    class KernelParent {\n        constructor(opts) {\n            opts = opts || {};\n            if (typeof opts.spawnChannel !== 'function') {\n                throw new Error('KernelParent: spawnChannel(ref, creds) required');\n            }\n            this._spawnChannel        = opts.spawnChannel;\n            this._resolveCredentials  = opts.resolveCredentials || (async () => null);\n            this.mounts               = new KMounts();\n            this.broker               = new KBroker({\n                kernelId: opts.kernelId || 'k-top',\n                ui:       opts.brokerUi || null\n            });\n        }\n\n        // Spawn + register a child vault under `prefix`. Returns { mountId, ref }.\n        async mount(opts) {\n            const prefix = opts.prefix, ref = opts.ref, label = opts.label;\n            const creds = await this._resolveCredentials(ref);\n            if (!creds || !creds.vaultKey) {\n                throw codeError('EUNREACH', 'no credentials for ref ' + ref);\n            }\n            // spawnChannel owns the bring-up AND its own cleanup on failure.\n            const channel = await this._spawnChannel(ref, creds);\n            const mountId = 'm-' + ref;\n            this.mounts.add({ mountId, prefix, ref, channel, label, meta: opts.meta || {} });\n            return { mountId, ref };\n        }\n\n        async unmount(mountId) {\n            const m = this.mounts.remove(mountId);\n            if (!m) return { unmounted: false };\n            try { m.channel && m.channel.close(); } catch (_) {}\n            // The broker log is intentionally retained for audit (the entries outlive the mount).\n            // channel is returned so a DOM caller can tear down any iframe stashed on it.\n            return { unmounted: true, mountId, meta: m.meta || null, channel: m.channel || null };\n        }\n\n        list() {\n            return this.mounts.list().map(function (m) {\n                return { mountId: m.mountId, ref: m.ref, prefix: m.prefix, label: m.label, isolation: 'isolated' };\n            });\n        }\n\n        // Cross-mount relay. Returns null when the path is local (caller does the local op);\n        // otherwise mediates via the broker and relays over the child channel (Edge 2).\n        async relay(op, args) {\n            const hit = this.mounts.resolve(args.path);\n            if (!hit) return null;                              // local \u2014 caller handles\n            const credentialClass = args.credential ? 'perRequest-rw' : 'standing';\n            const med = await this.broker.mediate(op, hit.mount.mountId, hit.rest, credentialClass);\n            if (med.decision !== 'allow') {\n                this.broker.finalize(med.entryId, 'ECONSENT');\n                throw codeError('ECONSENT', 'Broker denied');\n            }\n            try {\n                const res = await hit.mount.channel.request('vfs.' + op,\n                    { path: hit.rest, data: args.data, credential: args.credential },\n                    { sensitive: !!args.data || op === 'read' });\n                this.broker.finalize(med.entryId, 'ok');\n                return res;\n            } catch (err) {\n                this.broker.finalize(med.entryId, err.code || 'EPROTO');\n                throw err;\n            }\n        }\n    }\n\n    globalThis.KernelParent = KernelParent;\n})();\n\n</script>\n<script>\n/* =================================================================================\n   Kernel app handlers \u2014 register vfs.* on a SecureChannel  (Phase 2)\n\n   globalThis.registerKernelVfsHandlers(channel, ctx) \u2014 the kernel-side bodies that\n   handle relayed cross-mount requests OR direct app\u2192kernel requests over the bridge.\n   Both gates of two-sided authority (\u00a79) are enforced here:\n     \u2022 AppPermissions.isFloor(verb, path)  \u2192 EPROTECTED   (non-grantable; .vault/**, app.json)\n     \u2022 AppPermissions.can(perm, cap, path) \u2192 EPERM        (child's own app.json grant)\n   PLUS the server-edge writability check \u2192 EREADONLY.\n\n   The child runs THIS code. A parent's broker can grant relay access, but only the\n   child's policy decides if the op happens \u2014 which is the entire point of\n   \"credential is necessary, not sufficient.\" (Architect pack \u00a79.)\n\n   Push errors are surfaced \u2014 silent push failures used to misreport WRITE success\n   while the bytes never persisted; we treat that as EUNREACH so callers can retry\n   or escalate. (Reviewer fix M1.)\n\n   ctx = { dataSource, perm, vault?, onUpdated? }\n     dataSource : VaultDataSource (provides getFileBytes / listFolder / saveFile /\n                  deleteFile / writable)\n     perm       : AppPermissions.parsePermissions(appJson) result\n     vault      : SGVault instance (used for .push() \u2014 child's own Edge 1)\n     onUpdated  : optional (path) => void \u2014 fires on successful write/delete\n   ================================================================================= */\n\n;(function () {\n    'use strict';\n\n    if (!globalThis.AppPermissions) {\n        throw new Error('kernel-app-handlers requires AppPermissions (load app-permissions.js first)');\n    }\n    const AP = globalThis.AppPermissions;\n\n    function codeError(code, msg) { const e = new Error(msg); e.code = code; return e; }\n\n    // Map a verb to the AppPermissions capability used for the grant check.\n    // list shares the read grant (architect pack \u00a74 \u2014 list is a tree-walk read).\n    function _capabilityFor(op) {\n        switch (op) {\n            case 'read':\n            case 'list':   return 'fs.read';\n            case 'write':  return 'fs.write';\n            case 'delete': return 'fs.delete';\n            case 'mkdir':  return 'fs.mkdir';\n            case 'move':   return 'fs.move';\n            default:       return null;\n        }\n    }\n\n    // Verbs that bear the WRITE-side gate. Floor and capability are the same checks\n    // shipped at the top kernel \u2014 we run them on the child side too.\n    function _gate(op, path, perm) {\n        if (typeof path !== 'string') throw codeError('ENOENT', 'path required');\n        // The floor uses 'read' / 'write' (etc.) directly; map 'list' to 'read'.\n        const floorVerb = (op === 'list') ? 'read' : op;\n        if (AP.isFloor(floorVerb, path)) throw codeError('EPROTECTED', 'protected path');\n        const cap = _capabilityFor(op);\n        if (!cap) throw codeError('EPERM', 'unknown op');\n        if (!AP.can(perm, cap, path)) throw codeError('EPERM', 'no capability');\n    }\n\n    function _splitPath(path) {\n        const slash = path.lastIndexOf('/');\n        return {\n            dir:  slash > 0 ? '/' + path.slice(0, slash) : '/',\n            name: path.slice(slash + 1)\n        };\n    }\n\n    async function _safePush(vault) {\n        if (!vault || typeof vault.push !== 'function') return;\n        try { await vault.push(); }\n        catch (err) {\n            // M1: do not swallow. The write landed in the working tree but the server\n            // never received it \u2014 that's the silent data-loss pattern KneeScore hit.\n            throw codeError('EUNREACH', 'push failed: ' + (err && err.message || String(err)));\n        }\n    }\n\n    function registerKernelVfsHandlers(channel, ctx) {\n        if (!channel || typeof channel.handle !== 'function') {\n            throw new Error('registerKernelVfsHandlers: channel.handle required');\n        }\n        if (!ctx || !ctx.dataSource) {\n            throw new Error('registerKernelVfsHandlers: ctx.dataSource required');\n        }\n        const ds       = ctx.dataSource;\n        const perm     = ctx.perm || AP.parsePermissions(null);\n        const vault    = ctx.vault    || null;\n        const onUpdate = ctx.onUpdated || null;\n\n        channel.handle('vfs.read', async function (p) {\n            const path = p && p.path;\n            _gate('read', path, perm);\n            const buf = await ds.getFileBytes(path);\n            return buf instanceof Uint8Array ? buf : new Uint8Array(buf || []);\n        });\n\n        channel.handle('vfs.list', async function (p) {\n            const raw   = (p && p.path) || '';\n            _gate('list', raw, perm);\n            const folder = raw === '' ? '/' : (raw.charAt(0) === '/' ? raw : '/' + raw);\n            const entries = ds.listFolder(folder) || [];\n            return entries;\n        });\n\n        channel.handle('vfs.write', async function (p) {\n            const path = p && p.path;\n            _gate('write', path, perm);\n            if (!ds.writable) throw codeError('EREADONLY', 'Read-only vault');\n            const { dir, name } = _splitPath(path);\n            const data = p.data instanceof Uint8Array ? p.data : new Uint8Array(p.data || []);\n            await ds.saveFile(dir, name, data);\n            await _safePush(vault);\n            if (onUpdate) { try { onUpdate(path); } catch (_) {} }\n            return { ok: true, size: data.length, path };\n        });\n\n        channel.handle('vfs.delete', async function (p) {\n            const path = p && p.path;\n            _gate('delete', path, perm);\n            if (!ds.writable) throw codeError('EREADONLY', 'Read-only vault');\n            const { dir, name } = _splitPath(path);\n            await ds.deleteFile(dir, name);\n            await _safePush(vault);\n            if (onUpdate) { try { onUpdate(path); } catch (_) {} }\n            return { ok: true, path };\n        });\n\n        channel.handle('vfs.mkdir', async function (p) {\n            const path = p && p.path;\n            _gate('mkdir', path, perm);\n            if (!ds.writable) throw codeError('EREADONLY', 'Read-only vault');\n            const target = path.charAt(0) === '/' ? path : '/' + path;\n            await ds.createFolder(target);\n            await _safePush(vault);\n            return { ok: true, path };\n        });\n    }\n\n    globalThis.registerKernelVfsHandlers = registerKernelVfsHandlers;\n})();\n\n</script>\n<script>\n/* =================================================================================\n   Kernel bootstrap \u2014 port-side handshake + vault open + handler registration  (Phase 2)\n\n   globalThis.bootKernelOnPort(port, opts) \u2014 runs the child kernel's boot sequence\n   AGAINST AN ALREADY-RECEIVED PORT. Splitting this out (vs. inlining inside the\n   build-time KERNEL_BOOTSTRAP_JS) means the production code is also the code under\n   test \u2014 addresses reviewer finding M4 (the prior bootstrap had no test coverage\n   because tests used a hand-rolled TestKernel).\n\n   The window.message listener that receives the port is still inline in\n   build-kernel-shell-bundle.py \u2014 that line cannot move into a unit test (it touches\n   the `window` object). But everything AFTER the port is in hand lives here.\n\n   opts = {\n     // factories \u2014 injected so tests can pass synthetic implementations without mocks\n     vaultFactory  (vaultKey, accessToken, endpoint) \u2192 Promise<SGVault-like>\n     dataSourceFactory (vault, accessToken)         \u2192 VaultDataSource-like\n     appJsonReader (vault)                          \u2192 Promise<appJsonObject|null>\n     // configuration\n     endpointFor   (vaultKey)                       \u2192 endpoint URL (defaults to dev)\n     cid           handshake cid (echoed from init message)\n     expectSensitive  default true\n     onReady       optional callback(payload) after handlers registered\n     onError       optional callback(err)\n   }\n\n   Returns the SecureChannel (already past handshake; secrets handler registered).\n   The caller can await secrets delivery via `await new Promise(r => opts.onReady=r)`\n   or by inspecting the resolved channel.\n   ================================================================================= */\n\n;(function () {\n    'use strict';\n\n    function need(name, val) {\n        if (val == null) throw new Error('bootKernelOnPort: missing ' + name);\n        return val;\n    }\n    function codeError(code, msg) { const e = new Error(msg); e.code = code; return e; }\n\n    // Default factories use the shipped libraries. Tests override.\n    function _defaultVaultFactory(SGSend, SGVault) {\n        return async function (vaultKey, accessToken, endpoint) {\n            const sgSend = new SGSend({ endpoint: endpoint });\n            if (accessToken) sgSend.token = accessToken;\n            return SGVault.open(sgSend, vaultKey);\n        };\n    }\n    function _defaultDataSourceFactory(VaultDataSource) {\n        return function (vault, accessToken) { return new VaultDataSource(vault, accessToken || null); };\n    }\n    async function _defaultAppJsonReader(vault) {\n        // Try the new location first (.vault/app.json), then the shipped legacy root.\n        for (const p of ['.vault/app.json', 'app.json']) {\n            try {\n                const bytes = await vault.getFileBytes(p);\n                if (!bytes) continue;\n                const txt   = new TextDecoder().decode(bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes));\n                return JSON.parse(txt);\n            } catch (_) { /* not found / not JSON \u2192 try next */ }\n        }\n        return null;\n    }\n\n    async function bootKernelOnPort(port, opts) {\n        opts = opts || {};\n        need('port', port);\n        const SC = need('SecureChannel', globalThis.SecureChannel);\n        const AP = need('AppPermissions', globalThis.AppPermissions);\n        const registerHandlers = need('registerKernelVfsHandlers', globalThis.registerKernelVfsHandlers);\n\n        const vaultFactory      = opts.vaultFactory      || _defaultVaultFactory(globalThis.SGSend, globalThis.SGVault);\n        const dataSourceFactory = opts.dataSourceFactory || _defaultDataSourceFactory(globalThis.VaultDataSource);\n        const appJsonReader     = opts.appJsonReader     || _defaultAppJsonReader;\n        const endpointFor       = opts.endpointFor       || function () { return opts.endpoint || 'https://dev.send.sgraph.ai'; };\n\n        const ch = await SC.accept(port, { expectSensitive: opts.expectSensitive !== false, cid: opts.cid });\n\n        // Register the `secrets` handler synchronously after accept resolves \u2014 M4: the\n        // race in the prior bootstrap was that handlers were attached inside the secrets\n        // handler body, after async work; a second secrets message arriving in the same\n        // tick could double-invoke. Idempotence is the responder's job.\n        let booted = false;\n        ch.handle('secrets', async function (payload) {\n            if (booted) throw codeError('EPROTO', 'secrets replay');\n            booted = true;\n            const vaultKey = payload && payload.vaultKey;\n            const token    = payload && payload.accessToken;\n            // M5: endpoint comes from the secrets payload (or factory), never hardcoded.\n            const endpoint = (payload && payload.endpoint) || endpointFor(vaultKey);\n            if (!vaultKey) throw codeError('EPROTO', 'missing vaultKey');\n\n            let vault;\n            try { vault = await vaultFactory(vaultKey, token || null, endpoint); }\n            catch (err) { throw codeError('EUNREACH', 'vault open failed: ' + (err && err.message || err)); }\n\n            const dataSource = dataSourceFactory(vault, token || null);\n            const appJson    = await appJsonReader(vault);\n            const perm       = AP.parsePermissions(appJson);\n\n            registerHandlers(ch, {\n                dataSource: dataSource,\n                perm:       perm,\n                vault:      vault,\n                onUpdated:  opts.onUpdated || null\n            });\n\n            // Signal ready to the parent (responder.send works both ways \u2014 review B1).\n            const readyPayload = { kernelId: 'k-' + (vault._vaultId || (Date.now().toString(36))) };\n            try { await ch.send('ready', readyPayload); } catch (_) {}\n            if (typeof opts.onReady === 'function') {\n                try { opts.onReady(readyPayload); } catch (_) {}\n            }\n            return readyPayload;\n        });\n\n        return ch;\n    }\n\n    globalThis.bootKernelOnPort = bootKernelOnPort;\n})();\n\n</script>\n<script>\n(function () {\n    'use strict';\n    function boot(e) {\n        if (!e.data || e.data.type !== 'init') return;\n        window.removeEventListener('message', boot);\n        var port = e.ports && e.ports[0];\n        if (!port) { console.error('[kernel] no port on init'); return; }\n        globalThis.bootKernelOnPort(port, { cid: e.data.cid, expectSensitive: true })\n            .catch(function (err) { console.error('[kernel] handshake failed', err); });\n    }\n    window.addEventListener('message', boot);\n})();\n</script>\n</head><body></body></html>"; })();
